export function calculateBackoffMs(attempt: number, baseDelayMs: number = 1000): number {
  const jitter = Math.random() * 0.1 * baseDelayMs;
  return Math.min(baseDelayMs * Math.pow(2, attempt) + jitter, 30000);
}

