export class RateLimiter {
  private requestCount = 0;
  private resetTime = Date.now() + 60000;

  canMakeRequest(limit: number): boolean {
    if (Date.now() > this.resetTime) {
      this.requestCount = 0;
      this.resetTime = Date.now() + 60000;
    }
    return this.requestCount < limit;
  }
}

export async function validateStagingDeployment(version: string): Promise<{ok: boolean; errors: string[]}> {
  const errors: string[] = [];
  if (!version.match(/^v\d+\.\d+\.\d+/)) errors.push('Invalid version format');
  return { ok: errors.length === 0, errors };
}

export function aggregateMetrics(values: number[], aggregationType: 'sum' | 'avg' | 'max'): number {
  if (aggregationType === 'sum') return values.reduce((a, b) => a + b, 0);
  if (aggregationType === 'avg') return values.reduce((a, b) => a + b, 0) / values.length;
  return Math.max(...values);
}

export function validateFilterInput(input: unknown): input is Record<string, unknown> {
  return typeof input === 'object' && input !== null && !Array.isArray(input);
}

export function sanitizeFilterValue(value: string): string {
